CREATE OR REPLACE VIEW doc_extract.current AS
SELECT * EXCEPT(rn) FROM (
  SELECT *, ROW_NUMBER() OVER (
    PARTITION BY doc_id, field_path ORDER BY extracted_at DESC
  ) rn
  FROM doc_extract.extractions
) WHERE rn = 1;
